(raw => {
  const DDDS = new Set([11,12,13,14,15,16,17,18,19,21,22,24,27,28,
    31,32,33,34,35,37,38,41,42,43,44,45,46,47,48,49,
    51,53,54,55,61,62,63,64,65,66,67,68,69,
    71,73,74,75,77,79,81,82,83,84,85,86,87,88,89,
    91,92,93,94,95,96,97,98,99]);

  let d = (raw ?? "").toString().replace(/\D/g, "").replace(/^0+/, "");

  // remove o DDI só quando o que sobra ainda tem tamanho nacional
  if (d.length >= 12 && d.startsWith("55")) d = d.slice(2);
  if (d.length !== 10 && d.length !== 11) return "";

  const ddd = d.slice(0, 2);
  let loc = d.slice(2);
  if (!DDDS.has(Number(ddd))) return "";

  if (loc.length === 8) {
    if ("6789".includes(loc[0])) loc = "9" + loc;   // celular legado
    else if (!"2345".includes(loc[0])) return "";   // prefixo inexistente
    // 2,3,4,5 = fixo -> fica com 8 dígitos
  } else if (loc[0] !== "9") {
    return "";
  }

  return "55" + ddd + loc;
})($('Webhook').first().json.body.conversation.meta.sender.phone_number)
}}

